export type Category = "PDF" | "Office" | "Calculators" | "SEO" | "Social Media" | "Video & Audio" | "Formatters" | "Encoders" | "Generators" | "Text" | "Converters";

export interface ToolMeta {
  slug: string;
  name: string;
  short: string;
  description: string;
  category: Category;
  icon: string;          // lucide icon name (components/Icon.tsx)
  keywords: string[];
  popular?: boolean;
  server?: boolean;   // true = uses our API (fetches the URL / calls a service); FAQ text adapts
  about: string[];
  faq?: { q: string; a: string }[];
}

export interface CategoryMeta { name: Category; slug: string; blurb: string; icon: string; description: string; color: string }

